using FreshFoundation;
using System.Text.Json;
using System.Text.Json.Serialization;
internal static class CatalogChecks
{
    public static int Run()
    {
        string root=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-run-catalog-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string file=Path.Combine(root,"data001Slot.bin");File.WriteAllBytes(file,WorkspaceSyntheticSamples.Slot());var tests=new List<object>();int failures=0;
        void Assert(bool ok){if(!ok)throw new Exception("Synthetic catalog assertion failed.");}void Reject(Action a){bool rejected=false;try{a();}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}catch(InvalidDataException){rejected=true;}Assert(rejected);}void Test(string name,Action a){try{a();tests.Add(new{name,status="PASS"});}catch(Exception e){failures++;tests.Add(new{name,status="FAIL",error=e.Message});}}
        EditorWorkspace Open(){var w=new EditorWorkspace();w.Open(file);return w;}
        var origin=new CatalogOrigin("SYNTHETIC TEST ONLY","CC0 synthetic labels","synthetic");GameCatalogEntry Entry(GameCatalogKind kind,uint id,uint? slot=null)=>new(kind,id,new(){["en"]="SYNTHETIC apple",["zh-CN"]="合成苹果"},"Synthetic",Origin:origin,DeclaredStatus:CatalogItemStatus.VERIFIED_ITEM,DeclaredMaximumQuantity:9999999,RequiredSlotLevel:slot);
        Test("explicit local multilingual catalog claims cannot self-verify",()=>{var options=new JsonSerializerOptions();options.Converters.Add(new JsonStringEnumConverter());File.WriteAllText(Path.Combine(root,"catalog.json"),JsonSerializer.Serialize(new GameCatalogFile(1,[Entry(GameCatalogKind.Item,0x04000031),Entry(GameCatalogKind.Skill,0x04000031)]),options));string locale="en";var c=GameCatalog.LoadDirectory(root,()=>locale);Assert(c.Entries.All(e=>e.EffectiveStatus==CatalogItemStatus.KNOWN_ITEM));Assert(c.Label(CatalogNamespace.Item,0x04000031)=="SYNTHETIC apple");locale="zh-CN";Assert(c.Label(CatalogNamespace.Item,0x04000031)=="合成苹果"&&c.Search("苹果").Count==2&&c.Search("04000031").Count==2);var unknown=new GameCatalog([Entry(GameCatalogKind.Item,1) with{Origin=null}]);Assert(unknown.Entries[0].EffectiveStatus==CatalogItemStatus.UNKNOWN_ITEM);});
        Test("catalog keys reject enum and equipment-kind collisions",()=>{Reject(()=>new GameCatalog([Entry((GameCatalogKind)999,1)]));Reject(()=>new GameCatalog([Entry(GameCatalogKind.Weapon,1) with{EquipmentKind=2}]));Reject(()=>new GameCatalog([Entry(GameCatalogKind.Item,1) with{EquipmentKind=1}]));var c=new GameCatalog([Entry(GameCatalogKind.Weapon,1),Entry(GameCatalogKind.Armor,1) with{Names=new(){["en"]="SYNTHETIC armor"}}]);Assert(c.Label(CatalogNamespace.Equipment,1,1)!=c.Label(CatalogNamespace.Equipment,1,2)&&c.Find(GameCatalogKind.Weapon,1,2)==null);});
        Test("money points bounded by original values not storage maxima",()=>{var d=new DomainEditor(Open());d.SetMoney(0);d.SetMoney(2000);d.SetPoints(0);d.SetPoints(5000);Reject(()=>d.SetMoney(2001));Reject(()=>d.SetPoints(5001));Assert(d.Character().Money==2000&&d.Character().Points==5000);});
        Test("catalog declared cap cannot authorize original-total increase or new ID",()=>{var d=new DomainEditor(Open());Reject(()=>d.SetItemQuantity(0,10000));Reject(()=>d.AddKnownItem(0x04000031,1));Reject(()=>d.AddKnownItem(999,1));d.SetItemQuantity(0,9998);int record=d.AddKnownItem(0x04000031,1);Assert(record==1&&d.Inventory().Where(i=>i.Id==0x04000031).Sum(i=>i.Quantity)==9999);Reject(()=>d.SetItemQuantity(1,2));d.DeleteItem(0);Assert(d.Inventory()[0].Quantity==0);});
        void Rewrite(string path,Action<EditorWorkspace> edit){var w=new EditorWorkspace();w.Open(path);edit(w);var requests=w.Document!.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.DataCoordinate!=null&&!w.PrimitiveBytes(p.i)!.SequenceEqual(w.PrimitiveBytes(p.i,true)!)).Select(p=>new PrimitiveReplacement(p.i,w.PrimitiveBytes(p.i,true)!,w.PrimitiveBytes(p.i)!)).ToArray();File.WriteAllBytes(path,ExperimentalStructuralSerializer.Replace(w.Document,requests).CopyFileBytes());}
        Test("same-ID multi-record aggregate ceiling cannot be bypassed",()=>{string p=Path.Combine(root,"duplicates.bin");File.Copy(file,p);Rewrite(p,w=>{int id=w.Document!.Structure.Events.Select((e,i)=>(e,i)).Where(p=>p.e.Identifier==2940755215).Last().i;w.Apply(id,DomainEditor.UIntBytes(0x04000031));});var w=new EditorWorkspace();w.Open(p);var d=new DomainEditor(w);Assert(d.OriginalItemTotalCeiling(0x04000031)==10003);d.SetItemQuantity(0,9998);Reject(()=>d.AddKnownItem(0x04000031,2));d.AddKnownItem(0x04000031,1);Reject(()=>d.SetItemQuantity(2,5));});
        Test("anomalous original values remain readable but read-only",()=>{string p=Path.Combine(root,"anomalous.bin");File.Copy(file,p);Rewrite(p,w=>{var ev=w.Document!.Structure.Events.Select((e,i)=>(e,i));w.Apply(ev.First(p=>p.e.Identifier==2249897735).i,DomainEditor.IntBytes(-1));w.Apply(ev.First(p=>p.e.Identifier==2349967638).i,DomainEditor.IntBytes(-1));});var w=new EditorWorkspace();w.Open(p);var d=new DomainEditor(w);Assert(d.Character().Money==-1&&!d.CanEditMoney&&d.Inventory()[0].Quantity==-1);Reject(()=>d.SetMoney(0));Reject(()=>d.SetItemQuantity(2,3));Reject(()=>d.AddKnownItem(0x04000032,1));Reject(()=>d.DeleteItem(0));});
        Test("decoration selector requires explicit 1..4 levels and never enables writes",()=>{var c=new GameCatalog([Entry(GameCatalogKind.Decoration,1,1),Entry(GameCatalogKind.Decoration,2,2),Entry(GameCatalogKind.Decoration,3,0),Entry(GameCatalogKind.Decoration,4,5),Entry(GameCatalogKind.Decoration,5)]);Assert(c.DecorationsForKnownSlot(null).Count==0&&c.DecorationsForKnownSlot(0).Count==0&&c.DecorationsForKnownSlot(5).Count==0&&c.DecorationsForKnownSlot(1).Single().Id==1&&c.DecorationsForKnownSlot(4).Count==2);});
        File.WriteAllText("test-results-catalog.json",JsonSerializer.Serialize(new{executedAtUtc=DateTimeOffset.UtcNow,scope="SYNTHETIC catalog and conservative-operation-policy tests; no game validity claim",tests,failures},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Catalog focused groups={tests.Count}; failures={failures}");return failures==0?0:1;
    }
}
